-- Measures completed flights while a confirmed taxi ride is active.

local Constants = APR.NavigationConstants.NavigationTaxi

local taxi = APR.taxiData
local Shared = APR.taxiData._helpers
local Now = Shared.Now
local Number = Shared.Number
local Position = Shared.Position
local Price = Shared.Price

function taxi:CanTake(nodeID)
    local quote, money = self:GetQuote(nodeID), GetMoney and GetMoney() or 0
    if not quote or not Price(money) or quote.priceCopper > money then return false end
    return true, quote.slotIndex
end--[[APR_DIAG]]; taxi.CanTake = APRTrace("APR-Core/features/navigation/taxi/TaxiMeasurements.lua:17:taxi:CanTake#1", taxi.CanTake)--[[/APR_DIAG]]

function taxi:StartMeasurement(slot)
    if not self.currentNodeID or not self.liveOffers then return end
    for destinationID, offer in pairs(self.liveOffers) do
        if offer.slotIndex == slot then
            -- Keep the whole offered sequence. A flight with connections must
            -- never overwrite the independent timings of its individual legs.
            local snapshot = self:GetSnapshotKey()
            self.measurement = {
                from = self.currentNodeID,
                to = destinationID,
                signature = offer.signature,
                snapshot = snapshot,
                playerID = APR.PlayerID,
                data = self:GetCharacterData(snapshot),
                destination = Position(destinationID),
                requestedAt = Now(),
                announcementDestination = self:GetNodeName(destinationID),
            }
            self:RefreshMeasurementActivity()
            return
        end
    end
end--[[APR_DIAG]]; taxi.StartMeasurement = APRTrace("APR-Core/features/navigation/taxi/TaxiMeasurements.lua:23:taxi:StartMeasurement#2", taxi.StartMeasurement)--[[/APR_DIAG]]

function taxi:PollMeasurement()
    local measurement = self.measurement
    if not measurement then return end
    if
        measurement.playerID ~= APR.PlayerID
        or measurement.snapshot ~= self:GetSnapshotKey()
        or (UnitIsDeadOrGhost and UnitIsDeadOrGhost("player"))
    then
        self.measurement = nil
        return
    end
    if UnitOnTaxi and UnitOnTaxi("player") then
        if not measurement.started and measurement.announcementDestination and APR.announcements then
            APR.announcements:Send("flight", "ANNOUNCE_FLIGHT", nil, measurement.announcementDestination)
        end
        measurement.started = measurement.started or Now()
        return
    end
    if not measurement.started then
        -- A failed boarding request must not capture a later, unrelated flight.
        if Now() - measurement.requestedAt > 10 then self.measurement = nil end
        return
    end

    self.measurement = nil
    if not measurement.signature or not measurement.destination or not UnitPosition then return end
    local playerX, playerY, _, instanceID = UnitPosition("player")
    local destination = measurement.destination
    if not Number(playerX) or not Number(playerY) or not Number(instanceID) then return end
    if
        instanceID ~= destination.instanceID
        or (playerX - destination.x) ^ 2 + (playerY - destination.y) ^ 2 > 150 ^ 2
    then
        return
    end

    -- Being off the taxi only confirms arrival near the intended destination.
    -- Death, disconnection and a premature landing leave no usable measurement.
    local seconds = Now() - measurement.started
    if seconds > 1 and measurement.data then
        measurement.data.durations[measurement.signature] = { seconds = seconds, measuredAt = time and time() }
        self:InvalidateEdges()
        if APR.navigation then
            APR.navigation:InvalidatePathCache()
            APR.navigation:RequestUpdate()
        end
    end
end--[[APR_DIAG]]; taxi.PollMeasurement = APRTrace("APR-Core/features/navigation/taxi/TaxiMeasurements.lua:47:taxi:PollMeasurement#3", taxi.PollMeasurement)--[[/APR_DIAG]]
